use crc32fast::hash;
use tag_editor::shazam::spectrogram::{FrequencyPeak, Signature};

// Generated by SongRec's encode_to_binary at fb501dd991f38f5d1d3b567dbf4d295beb47d8e7.
const SONGREC_SIGNATURE: &[u8] = include_bytes!("fixtures/songrec-peaks.sig");

fn reference_signature() -> Signature {
    let peak = |pass, magnitude, bin| FrequencyPeak {
        pass,
        magnitude,
        bin,
    };
    Signature::new(
        16_000,
        48_000,
        [
            vec![peak(7, 1234, 4096), peak(320, 4321, 8192)],
            vec![peak(12, 2048, 16384)],
            vec![],
            vec![],
            vec![],
        ],
    )
}

fn assert_same_signature(actual: &Signature, expected: &Signature) {
    assert_eq!(actual.sample_rate, expected.sample_rate);
    assert_eq!(actual.num_samples, expected.num_samples);
    let fields = |peaks: &[FrequencyPeak]| {
        peaks
            .iter()
            .map(|peak| (peak.pass, peak.magnitude, peak.bin))
            .collect::<Vec<_>>()
    };
    assert_eq!(
        actual.peaks_by_band.each_ref().map(|peaks| fields(peaks)),
        expected.peaks_by_band.each_ref().map(|peaks| fields(peaks))
    );
}

fn with_lengths(lengths: &[(usize, u32)]) -> Vec<u8> {
    let mut bytes = SONGREC_SIGNATURE.to_vec();
    for &(offset, length) in lengths {
        bytes[offset..offset + 4].copy_from_slice(&length.to_le_bytes());
    }
    let crc = hash(&bytes[8..]);
    bytes[4..8].copy_from_slice(&crc.to_le_bytes());
    bytes
}

#[test]
fn an_empty_signature_round_trips() {
    let original = Signature::new(16_000, 16_000, Default::default());
    let decoded = Signature::decode(&original.encode()).unwrap();
    assert_same_signature(&decoded, &original);
}

#[test]
fn nonempty_signatures_match_the_independent_fixture() {
    let original = reference_signature();
    let encoded = original.encode();
    let decoded = Signature::decode(&encoded).unwrap();
    assert_same_signature(&decoded, &original);

    let independent = Signature::decode(SONGREC_SIGNATURE).unwrap();
    assert_same_signature(&independent, &original);
    assert_eq!(encoded, SONGREC_SIGNATURE);
}

#[test]
fn earlier_rune_signatures_counted_padding_in_peak_lengths() {
    // The old encoder counted the padded sizes of both TLVs (16 and 8).
    let earlier = with_lengths(&[(60, 16), (84, 8)]);
    let decoded = Signature::decode(&earlier).unwrap();
    assert_same_signature(&decoded, &reference_signature());
}

#[test]
fn invalid_lengths_and_checksum_are_rejected() {
    let wrong_length = (SONGREC_SIGNATURE.len() - 40) as u32;
    for (offset, error) in [(8, "bad length"), (52, "bad length2")] {
        assert_eq!(
            Signature::decode(&with_lengths(&[(offset, wrong_length)])).unwrap_err(),
            error
        );
    }
    assert_eq!(
        Signature::decode(&with_lengths(&[(60, SONGREC_SIGNATURE.len() as u32)])).unwrap_err(),
        "invalid peak block length"
    );
    let mut bad_crc = SONGREC_SIGNATURE.to_vec();
    bad_crc[4] ^= 1;
    assert_eq!(Signature::decode(&bad_crc).unwrap_err(), "bad checksum");
}
